from sympy import symbols, Eq
y,z,x = symbols('y z x')
expr = y**2 + 4*z**2
# Verify traces:
traces = {
    'x=k': Eq(expr, 2),  # ellipse for k=2
    'y=0': Eq(x, 4*z**2),
    'z=0': Eq(x, y**2),
}
print(expr)
print(traces)
# Check cross-section x=k: y^2 + 4 z^2 = k has ellipse for k>0, point for k=0, none for k<0.
for k in [-1,0,1,2]:
    if k > 0:
        print(f'k={k}: ellipse semiaxes sqrt({k}) and sqrt({k})/2')
    elif k == 0:
        print(f'k={k}: point at origin')
    else:
        print(f'k={k}: no real points')

